/* Scalable stack inventory and permanent character traits, on the selected B navigation. */
const RelicInventoryUI=(()=>{
    const M=MageRelics;let serial=0,query='',filter='all',page=0,market=false,result=null;
    const number=n=>new Intl.NumberFormat('en',{notation:n>=10000?'compact':'standard',maximumFractionDigits:n>=10000?1:2}).format(n);
    const rates=()=>{const v=MageVentureSpirits.production(state,state.ventureSpirits),m=M.modifiers(state.inventory,DungeonUI.clock());return {ore:v.ore,pearls:v.pearls,shards:Number(rate())*m.idleSpeed*m.idleYield};};
    const exact=n=>Number(n).toLocaleString('en',{maximumFractionDigits:2});
    const rarity=d=>`<small style="color:${MageRarity.colors[d.rarity]}">${MageRarity.tiers[d.rarity]}</small>`;
    const duration=d=>d.kind==='chest'?'Permanent traits':d.value+(d.kind==='echo'?' casts':' min');
    function quantities(attribute,current){return `<nav class="quantity-picker" aria-label="Choose quantity">${[...M.quantities,'max'].map(n=>`<button ${attribute}="${n}" aria-pressed="${String(current)===String(n)}">${n==='max'?'Max':n+'×'}</button>`).join('')}</nav>`;}
    function inventory(){const all=M.definitions.filter(d=>(market||state.inventory.stocks[d.id]>0)&&(filter==='all'||filter==='chests'&&d.kind==='chest'||filter==='items'&&d.kind!=='chest'||filter.startsWith('rarity-')&&d.rarity===Number(filter.slice(7)))&&d.name.toLowerCase().includes(query.toLowerCase())),pages=Math.max(1,Math.ceil(all.length/6));page=Math.max(0,Math.min(page,pages-1));return `<section class="page inventory-page"><div class="inventory-heading"><h2>Inventory</h2><div class="inventory-mode" role="group" aria-label="Inventory or trader"><button data-inv-market="bag" aria-pressed="${!market}">Bag</button><button data-inv-market="trader" aria-pressed="${market}">Trader</button></div></div><div class="collection-tools"><input data-inv-search aria-label="Search inventory" placeholder="Search items…" value="${esc(query)}"><select data-inv-filter aria-label="Filter inventory"><option value="all" ${filter==='all'?'selected':''}>All</option><option value="chests" ${filter==='chests'?'selected':''}>Chests</option><option value="items" ${filter==='items'?'selected':''}>Consumables</option>${MageRarity.tiers.map((n,i)=>`<option value="rarity-${i}" ${filter==='rarity-'+i?'selected':''}>${n}</option>`).join('')}</select></div><div class="inventory-grid">${all.slice(page*6,(page+1)*6).map(d=>`<button class="inventory-card" data-inv-item="${d.id}" style="--rarity:${MageRarity.colors[d.rarity]}" aria-label="${d.name}, ${MageRarity.tiers[d.rarity]}, ${state.inventory.stocks[d.id]} owned. ${market?'Trade':'Open details'}">${sprite(d.art)}<b class="stack-count">×${number(state.inventory.stocks[d.id])}</b><strong>${d.short}</strong><small>${d.kind==='chest'?MageRarity.tiers[d.rarity]:duration(d)}</small></button>`).join('')}</div>${!all.length?'<div class="inventory-empty">'+ui('book')+'<strong>No items here</strong><span>Earn loot while you play</span></div>':''}<div class="inventory-pagination"><button data-inv-page="-1" aria-label="Previous inventory page" ${page===0?'disabled':''}>←</button><span>${page+1} / ${pages}<small>${all.length} types · ${number(Object.values(state.inventory.stocks).reduce((a,b)=>a+b,0))} items</small></span><button data-inv-page="1" aria-label="Next inventory page" ${page===pages-1?'disabled':''}>→</button></div><div class="inventory-shortcuts"><button data-view="character">${ui('crest')} Character</button><button data-ground-items>${ui('book')} Waiting <b>${state.groundLoot.pending.length}</b></button></div></section>`;}
    function character(){const mode=state.characterMode||'idle',m=M.modifiers(state.inventory,DungeonUI.clock());return `<section class="page character-page"><div class="inventory-heading"><h2>Character</h2><nav class="character-tabs" aria-label="Character stat mode">${['idle','active'].map(v=>`<button data-character-mode="${v}" aria-pressed="${mode===v}">${ui(v==='idle'?'time':'power')}${v==='idle'?'Idle':'Active'}</button>`).join('')}</nav></div><div class="trait-preview">${ui('crest')}<strong>Permanent traits</strong><span>${mode==='idle'?number(m.idleSpeed)+'× cast rate':Math.round(420*m.activeCooldown)+'ms between casts'}</span></div><div class="trait-list">${M.stats.filter(s=>s.mode===mode).map(s=>{const v=M.value(state.inventory,s.id),max=v>=s.cap;return `<button class="trait-row" data-trait="${s.id}" style="--rarity:${MageRarity.colors[s.rarity]}">${ui(s.art)}<span><strong>${s.name}</strong><small>${MageRarity.tiers[s.rarity]} · ${max?'Max':('Next +'+s.step+'%')}</small></span><b>+${number(v)}%<i><em style="width:${v/s.cap*100}%"></em></i></b></button>`;}).join('')}</div></section>`;}
    function amount(d,action){const n=state.inventoryQuantity||1;if(n!=='max')return n;let max=state.inventory.stocks[d.id]||0;if(action==='buy'){const q=M.quote(state,{action,key:d.id,count:1,now:DungeonUI.clock(),rates:rates()});max=Math.floor(state.ore/q.unitPrice);}if(action==='use'&&d.kind==='time')max=Math.min(max,Math.floor(Math.max(0,43200-state.seconds)/(d.value*60)));return Math.min(1000000,max);}
    function detail(){const {key,action}=state.modal,d=M.find(key),count=amount(d,action),q=M.quote(state,{action,key,count,now:DungeonUI.clock(),rates:rates()}),verb=action==='open'?'Open':action==='use'?'Use':action==='buy'?'Buy':'Sell';return `<div class="inventory-detail"><div class="inventory-item-hero">${sprite(d.art)}<div><strong>${d.name}</strong>${rarity(d)}<small>Owned ×${exact(state.inventory.stocks[key])}</small></div><button class="info-button" data-inv-rules aria-label="How this item works">${glyph('info')}</button></div><nav class="inventory-actions" aria-label="Item action">${[d.kind==='chest'?'open':'use','buy','sell'].map(a=>`<button data-inv-action="${a}" aria-pressed="${action===a}">${a[0].toUpperCase()+a.slice(1)}</button>`).join('')}</nav>${quantities('data-inv-quantity',state.inventoryQuantity||1)}<div class="quantity-caption">Selected <b>×${exact(count)}</b>${state.inventoryQuantity==='max'?' · Maximum available':''}</div>${action==='open'?`<section class="rarity-odds relic-odds"><div class="row between"><strong>Trait rarity</strong><small>Idle / Active · 50 / 50</small></div><div class="odds-bar" aria-hidden="true">${M.chestOdds[d.rarity].map((n,i)=>`<i style="width:${n/100}%;background:${MageRarity.colors[i]}"></i>`).join('')}</div><div class="odds-grid">${M.chestOdds[d.rarity].map((n,i)=>`<div style="--rarity:${MageRarity.colors[i]}"><span>${MageRarity.tiers[i]}</span><b>${n/100}%</b></div>`).join('')}</div><small>1 permanent trait per chest · At cap → ${d.conversion} Ore</small></section>`:action==='use'?`<div class="item-use-preview">${d.kind==='time'?`${ui('time')}<strong>${number(d.value*count)}m production</strong><span>${metric('ore','+'+(q.production?.ore||0),'Ore received')}${metric('pearls','+'+(q.production?.pearls||0),'Pearls received')}${metric(resourceIcon(),'+'+(q.production?.shards||0),'Shards received')}</span>${VentureDevelopmentUI.materialSummary(q.production?.materials)}<small>Uses remaining idle time · Production only</small>`:d.kind==='focus'?`${ui('wind')}<strong>+20% active spell area</strong><span>+${number(d.value*count)} minutes · Duration stacks</span>`:`${ui('power')}<strong>One extra strike per active cast</strong><span>+${number(d.value*count)} charges · Charges stack</span>`}</div>`:`<div class="trade-total">${ui('ore')}<span>${action==='buy'?'Cost':'Receive'}<b>${exact(q.total||0)} Ore</b></span><small>${exact(action==='buy'?q.unitPrice||0:d.sell)} each · Earned currency</small></div>`}<button class="rune-button inventory-commit" data-inv-commit data-total="${q.total||0}" ${q.ok?'':'disabled'}>${verb} ×${exact(count)}</button>${!q.ok?`<p class="quantity-error" role="status">${count===0?(action==='buy'?'Not enough Ore':action==='use'&&d.kind==='time'&&state.inventory.stocks[key]>0?'No idle time remaining':'No items available'):q.reason}</p>`:''}</div>`;}
    function resultView(){const r=result;if(!r)return '';const d=M.find(r.key);return `<div class="inventory-result"><div class="batch-summary">${sprite(d.art)}<span><strong>${r.action==='open'?'Opened':r.action==='use'?'Used':r.action==='buy'?'Bought':'Sold'} ×${exact(r.count)}</strong><small>${d.short}</small></span></div>${r.action==='open'?`<div class="batch-gains">${Object.entries(r.gains).map(([id,n])=>{const s=M.stats.find(s=>s.id===id);return `<div style="--rarity:${MageRarity.colors[s.rarity]}">${ui(s.art)}<span>${s.name}<small>${s.mode==='idle'?'Idle':'Active'} · ${MageRarity.tiers[s.rarity]}</small></span><b>+${number(n)}%</b></div>`;}).join('')}</div>${r.converted?`<p class="quantity-caption">${r.converted} capped traits → +${exact(r.convertedOre)} Ore</p>`:''}`:r.production?`<div class="batch-resources">${metric('ore','+'+r.production.ore,'Ore received')}${metric('pearls','+'+r.production.pearls,'Pearls received')}${metric(resourceIcon(),'+'+r.production.shards,'Shards received')}</div>${VentureDevelopmentUI.materialSummary(r.production.materials)}`:`<p class="batch-effect">${r.action==='sell'?'+'+r.total+' Ore':r.action==='buy'?'−'+r.total+' Ore':d.kind==='focus'?'+'+r.focusSeconds/60+' min · +20% active area':'+'+r.echoCharges+' echo charges'}</p>`}<button class="rune-button" data-action="close">Done</button>${r.action==='open'?ShopGiftsUI.celebration(r):''}</div>`;}
    function onKills(source,amount){if(!amount)return;const total=state.inventory.progress[source]+amount;for(const drop of M.milestone(state,{source,total})){const d=M.find(drop.key);MageItemLoot.queue(state.groundLoot,{id:'earned-'+drop.id,kind:d.kind==='chest'?'relic':'consumable',key:d.id,rarity:d.rarity,realm:state.realm,source});}GroundLoot.refresh();}
    function openItem(key){state.inventoryQuantity??=1;openModal({type:'inventoryItem',key,action:market?'buy':M.find(key).kind==='chest'?'open':'use'});}
    function handle(el){if(el.hasAttribute('data-inv-rules')){openModal({type:'inventoryRules',key:state.modal.key,back:{...state.modal}});return true;}if(el.hasAttribute('data-inv-rules-back')){state.modal=state.modal.back;render(true);return true;}if(el.dataset.invItem){openItem(el.dataset.invItem);return true;}if(el.dataset.invMarket){market=el.dataset.invMarket==='trader';page=0;render();return true;}if(el.dataset.invPage){page+=Number(el.dataset.invPage);render(true);return true;}if(el.dataset.characterMode){state.characterMode=el.dataset.characterMode;render();return true;}if(el.dataset.trait){const s=M.stats.find(s=>s.id===el.dataset.trait);openModal({type:'trait',key:s.id});return true;}if(el.dataset.invAction){state.modal.action=el.dataset.invAction;render(true);phone.querySelector('[data-inv-action="'+el.dataset.invAction+'"]')?.focus();return true;}if(el.dataset.invQuantity){state.inventoryQuantity=el.dataset.invQuantity==='max'?'max':Number(el.dataset.invQuantity);render(true);phone.querySelector('[data-inv-quantity="'+el.dataset.invQuantity+'"]')?.focus();return true;}if(el.hasAttribute('data-inv-commit')){const {key,action}=state.modal,d=M.find(key),count=amount(d,action),out=M.transact(state,{id:'inventory-'+(++serial),key,action,count,now:DungeonUI.clock(),rates:rates(),expectedTotal:Number(el.dataset.total),samples:action==='open'?Array.from({length:count*2},()=>Math.random()):undefined});if(out.ok&&!out.duplicate){result=out.receipt;openModal({type:'inventoryResult'});if(action==='open')ShopGiftsUI.play(result);}else notify(out.reason||'Unable to complete action');return true;}return false;}
    function modal(m){if(m.type==='inventoryRules'){const d=M.find(m.key);return {heading:d.short,body:`<div class="inventory-rules">${sprite(d.art)}<p>${d.kind==='time'?'Grants current resource production within the remaining 12h idle window. Does not clear nodes or bosses, roll realm spells, expire buffs, or change daily resets.':d.kind==='chest'?'One permanent character trait per chest. Each rarity has its displayed odds; Idle and Active are equally likely. Capped traits convert to '+d.conversion+' Ore, 20% of the chest price.':d.kind==='focus'?'Adds 20% active spell area for the shown duration. Extra copies extend time without increasing strength.':'Adds one extra strike to each of the shown active casts. Charges from extra copies stack.'}</p><p>All trades use earned Ore. Prices and permanent gains shown apply to the whole batch.</p></div><button class="rune-button" data-inv-rules-back>Back to item</button>`};}if(m.type==='inventoryItem')return {heading:'Item details',body:detail()};if(m.type==='inventoryResult')return {heading:'Batch complete',body:resultView()};const s=M.stats.find(s=>s.id===m.key),v=M.value(state.inventory,s.id);return {heading:s.name,body:`<div class="trait-detail" style="--rarity:${MageRarity.colors[s.rarity]}">${ui(s.art)}<strong>+${number(v)}%</strong>${rarity(s)}<p>Permanent · ${s.mode==='idle'?'Idle farming':'Active spell clearing'}</p><p>Each find +${s.step}% · Maximum +${s.cap}%</p><small>Find traits in relic chests. At cap, further finds become Ore worth 20% of the chest price.</small></div><button class="rune-button" data-action="close">Done</button>`};}
    function seed(){query='';filter='all';page=0;market=false;M.definitions.forEach((d,i)=>M.grant(state.inventory,{id:'review-stock-'+d.id,key:d.id,count:d.kind==='chest'?[80,50,30,25,25][d.rarity]:i%2?2500:1250}));state.ore=25000;state.inventory.ranks.haste=12;state.inventory.ranks.cooldown=8;}
    function start(){document.addEventListener('input',e=>{if(e.target.hasAttribute('data-inv-search')){query=e.target.value;page=0;const position=e.target.selectionStart;render(true);const input=phone.querySelector('[data-inv-search]');input.focus();input.setSelectionRange(position,position);}});document.addEventListener('change',e=>{if(e.target.hasAttribute('data-inv-filter')){filter=e.target.value;page=0;render(true);}});}
    return {inventory,character,modal,handle,start,seed,onKills,rates,openItem};
})();
